{
  "sop_id": "SOP-013",
  "title": "BOQ review",
  "steps": [
    {
      "step_id": "S1",
      "name": "Open ticket on platform",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Complete template checklist",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Compare quantities to drawings",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Compare rates to schedule of rates and last three prices",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Write variance down line by line",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Write short summary of variance",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S7",
      "name": "Submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Wait for Operations confirmation",
      "role": "Executor",
      "type": "decision"
    },
    {
      "step_id": "A1",
      "name": "Incharge approval",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Rework",
      "role": "Executor",
      "type": "rework"
    },
    {
      "step_id": "A2",
      "name": "Lead approval (for big jobs or non-standard items)",
      "role": "Lead",
      "type": "approval"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "big jobs or non-standard items"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Operations",
      "item": "drawing revision or take-off confirmation",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.9
}
